function M:getXlsxActivityByOpenId(openId, isRechargeActivity)
    local xlsxName = isRechargeActivity and "active_recharge" or "active"
    local active = ConfigManager:getCfgByName(xlsxName)
    for _,itemData in pairs(active) do
        if (itemData.version == self.m_version) and (openId == itemData.open_id) then
            return itemData
        end
    end
    return nil
end

function M:refreshActivityXlsx()
    self.m_activityXlsxData = {}
    for _, itemData in pairs(self.m_tab_Node) do
        local openId = itemData.open_id
        self.m_activityXlsxData[openId] = self:getXlsxActivityByOpenId(openId, itemData.isRechargeActivity)
    end
    self.m_activityXlsxData[self.m_mainOpenId] = self:getXlsxActivityByOpenId(self.m_mainOpenId, false)
end

function M:updateNetData(newData)
