        openId = self.m_tab_Node[tab_index].open_id
    end
    local response = tab_index and responseData or responseData.response
    local itemData = self.m_serverDatas[openId]
    if openId == 227 then
        self:refreshEggsData(itemData, response)
    elseif openId == 228 then
        self:refreshTreeData(itemData, response)
    elseif openId == 229 then
        self:refreshShopData(itemData, response)
    elseif openId == 230 then
        self:refreshGiftRoomData(itemData, response)
    end
end

