function M:isOpenStatusByOpenId(tab_index)
    local openId = nil
    if tab_index and self.m_tab_Node[tab_index] and self.m_tab_Node[tab_index].open_id then
        openId = self.m_tab_Node[tab_index].open_id
    end
    if not openId then
        return false
    end
