function M:refreshData(response)
    self.m_data = response
    self.m_activityDatas = self:getActivityData(response)
    self.m_version = response.version
    self.m_charge_num = response.charge_sum or 0
    --self.m_package_refresh_time = response.gift_end_ts
    self.m_serverDatas = {}
    if response and response.charge_actives then
        for i, v in pairs(response.charge_actives) do
            if v.open_id == 230 then
                self.m_start_ts = v.start_ts
            end
        end
    end
    self:setCurDay(self:getCurDay())
    for _, itemData in pairs(self.m_tab_Node) do
        local openId = itemData.open_id
        self.m_serverDatas[openId] = {}
        if openId == 227 then
            -- 砸金蛋
            self:refreshEggsData(self.m_serverDatas[openId], response, itemData)
        elseif openId == 228 then
            -- 许愿树
            self:refreshTreeData(self.m_serverDatas[openId], response, itemData)
        elseif openId == 229 then
            -- 灵鹿集市
            self:refreshShopData(self.m_serverDatas[openId], response, itemData)
        elseif openId == 230 then
            -- 礼包屋
            self:refreshGiftRoomData(self.m_serverDatas[openId], response, itemData)
        end
    end
end

-- 礼包屋红点
function M:refreshGiftRoomRedDot(buyGiftLog)
    local isShowRedDot = false
    local new_year_giftData = ConfigManager:getCfgByName("new_year_gift") or {}
    local versionData = new_year_giftData[self.m_version] or {}
    local dayData = versionData[self.m_cur_day]
    if dayData and buyGiftLog and buyGiftLog.data then
        for index, data in pairs(buyGiftLog.data) do
            index = tonumber(index)
            local xlsxSeatGiftDatas = dayData[index] or {}
            local cid = data.cid
            local curGiftData = xlsxSeatGiftDatas[cid]
            if curGiftData then
                if cid > 0 then
                    curGiftData = xlsxSeatGiftDatas[cid]
                    if curGiftData.price <= 0 then
                        if data.times == 0 then
                            isShowRedDot = true
                            break
                        end
                    end
                end
            end
        end
    end
    return isShowRedDot
end

-- 灵鹿集市红点
function M:refreshExchangeRedDot(exchangeData)
    local isShowRedDot = false
    local new_year_exchangeData = ConfigManager:getCfgByName("new_year_exchange")
    local versionData = new_year_exchangeData[self.m_version]
    for _, itemData in pairs(versionData) do
        local curExchangeCount = exchangeData[itemData.id] or 0
        if curExchangeCount < itemData.times then
            local isExist = false
            for _, itemData in pairs(itemData.need_reward) do
                local awardData = RewardUtil:getProcessRewardData(itemData)
                isExist = (awardData.user_num >= awardData.data_num)
                if isExist then
                    break
                end
            end
            if isExist then
                isShowRedDot = true
                break
            end
        end
    end
    return isShowRedDot
end

