-- 许愿树红点
function M:refreshWishingTreeRedDot(response, gotAwardIds, serverTaskData)
    local openAstrictIndex = ConfigManager:getCommonValueById(610) or 0
    if (openAstrictIndex == 0) then
        local curTimer = UserDataManager:getServerTime()
        local targetTimer = ConfigManager:getCommonValueById(611) or curTimer
        if curTimer < targetTimer then
            return false
        end
    end
    local isShowRedDot = false
    for _, itemData in pairs(serverTaskData) do
        if (itemData.status == 1) then
            isShowRedDot = true
            break
        end
    end
    if not isShowRedDot then
        isShowRedDot = (response.score >= self:getWishingThreeAwardValue() and table.nums(gotAwardIds) < 7)
    end
    return isShowRedDot
end

--砸蛋红点
function M:refreshSmashEggRedDot(egg_times, daily_egg_times, gotAwardIds)
    gotAwardIds = gotAwardIds or {}
    local egg_rewardData = ConfigManager:getCfgByName("egg_reward")
    local versionData = egg_rewardData[self.m_version]
    local isShowRedDot = daily_egg_times > 0
    if not isShowRedDot then
        for i = 1, #versionData do
            local itemData = versionData[i]
            local itemSmashCount = itemData.time
            if (egg_times >= itemSmashCount) and (gotAwardIds[i] == nil) then
                isShowRedDot = true
            end
        end
    end
    return isShowRedDot
end

