function M:trimXlsxWishingTaskData()
    local tempData = {}
    local egg_rewardData = ConfigManager:getCfgByName("tree_quest")
    local versionData = egg_rewardData[self.m_version]
    for id, itemData in pairs(versionData) do
        if not tempData[itemData.sort] then
            tempData[itemData.sort] = {}
        end
        local sortList = tempData[itemData.sort]
        -- 1每日， 2 永久任务
        if itemData.sort == 1 then
            if not sortList[itemData.day] then
                sortList[itemData.day] = {}
            end
            table.insert(sortList[itemData.day], {
                id = id,
                xlsxData = itemData,
            })
        else
            table.insert(sortList, {
                id = id,
                xlsxData = itemData,
            })
        end
    end
    return tempData
end

