-- 修改阶梯礼包数据，判断规则：限购次数，VIP等级，累计金额，章节限制，章节范围限制
function M:trimEveryDayLadderBagData(curGiftData, data, pastRechargeMoneyCount)
    local cid = data.cid
    local isCanBuy = true
    if (curGiftData.time_limit > 0) then
        isCanBuy = data.times < curGiftData.time_limit
    end
    local userDataManager = UserDataManager
    local curVipLevel = userDataManager.user_data:getUserStatusDataByKey("vip")
    if isCanBuy and (curGiftData.vip > 0) then
        isCanBuy = curVipLevel >= curGiftData.vip
    end
    if isCanBuy and (curGiftData.add_recharge > 0) then
        isCanBuy = pastRechargeMoneyCount >= curGiftData.add_recharge
    end
    local curChapterId = userDataManager:getCurStage()
    if isCanBuy and (curGiftData.stage > 0) then
        isCanBuy = curChapterId >= curGiftData.stage
    end
    if isCanBuy and curGiftData.stage_limit and #curGiftData.stage_limit > 0 then
        local chapterLimit = curGiftData.stage_limit
        isCanBuy = curChapterId >= chapterLimit[1] and curChapterId <= chapterLimit[2]
    end
    cid = isCanBuy and cid or (cid - 1)
    -- 1. 只有一层，买完后要显示已售罄
    -- 2. 只有一层，不符合条件要隐藏
    if cid <= 0 then
        cid = (data.times <= 0) and 0 or 1  --times 买没买过
    end
    return cid, isCanBuy
end

-- 礼包屋礼包数据
function M:getGiftRoomData(buyGiftLog)
    local tempData = {}
    local curVip = UserDataManager.user_data:getUserStatusDataByKey("vip") or 0
    local season_data = UserDataManager.m_season_data or {}
    local curSeason = season_data.season or 0
    local new_year_giftData = ConfigManager:getCfgByName("new_year_gift")
    local versionData = new_year_giftData[self.m_version] or {}
    local dayData = versionData[self.m_cur_day]
    if dayData and buyGiftLog and buyGiftLog.data then
        for index, data in pairs(buyGiftLog.data) do
            index = tonumber(index)
            local xlsxSeatGiftDatas = dayData[index] or {}
            local cid = data.cid
            local curGiftData = xlsxSeatGiftDatas[cid]
            if curGiftData then
                -- 限购次数，VIP等级，累计金额，章节限制，章节范围限制
                local isCanBuy = true
                cid, isCanBuy = self:trimEveryDayLadderBagData(curGiftData, data, self.m_charge_num)
                -- <=0, 表示第一个礼包，第一个礼包不符合购买需求则隐藏礼包
                if cid > 0 then
                    curGiftData = xlsxSeatGiftDatas[cid]
                    table.insert(tempData, {
                        xlsxData = curGiftData,
                        cid = data.cid,
                        buyCount = data.times,
                        isCanBuy = isCanBuy,
                        index = index,
                        isSpecialPlace = false,
                    })
                end
            end
        end
    else
        Logger.logError("new_year_gift表缺少第"..tostring(self.m_version).. "期第"..tostring(self.m_cur_day).."天的配置")
    end
    table.sort(tempData, function(itemData1, itemData2)
        return itemData1.index < itemData2.index
    end)
    
    local returnData = {}
    local showCount = 3
    --local tempData = {1,2,3,4,5}        -- 数据内容
    local count =  math.floor(#tempData / showCount) + 1
    for i=1,count do
        for index = (i - 1) * showCount + 1,(i - 1) * showCount + showCount do
            if tempData[index] then
                if not returnData[i] then
                    returnData[i] = {}
                end
                table.insert(returnData[i], tempData[index] )
            end
        end
    end
    return returnData
end

-- 灵鹿集市数据
function M:getkancilShopData(serverExchangeData)
    local tempData = {}
    local curVip = UserDataManager.user_data:getUserStatusDataByKey("vip") or 0
    local season_data = UserDataManager.m_season_data or {}
    local curSeason = season_data.season or 0
    local new_year_exchangeData = ConfigManager:getCfgByName("new_year_exchange")
    local versionData = new_year_exchangeData[self.m_version]
    for id, itemData in pairs(versionData) do
        local curExchangeCount = serverExchangeData[id] or 0
        local awardData = RewardUtil:getProcessRewardData(itemData.need_reward[1])
        if (curVip >= itemData.vip) and (curSeason >= itemData.season) then
            if (itemData.season1 < 0) or (itemData.season1 == curSeason) then
                table.insert(tempData, {
                    id = id,
                    xlsxData = itemData,
                    userNum = awardData.user_num,
                    needNum = awardData.data_num,
                    curExchangeCount = curExchangeCount,
                    allCount = itemData.times,
                })
            end
        end
    end
    table.sort(tempData, function(itemData1, itemData2)
        local sortIndex1 = (itemData1.curExchangeCount >= itemData1.allCount) and 1 or -1
        local sortIndex2 = (itemData2.curExchangeCount >= itemData2.allCount) and 1 or -1
        if sortIndex1 ~= sortIndex2 then
            return sortIndex1 < sortIndex2
        else
            return itemData1.id < itemData2.id
        end
    end)
    return tempData
end

