-- 许愿树任务列表
function M:getWishingTaskData(serverData, selectIndex, openDay)
    if not self.m_xlsxWishingTaskData then
        self.m_xlsxWishingTaskData = self:trimXlsxWishingTaskData()
    end
    local selectTypeData = self.m_xlsxWishingTaskData[selectIndex]
    local curDayTaskData = selectTypeData
    if (selectIndex == 1) then
        curDayTaskData = selectTypeData[openDay] or {}
    end
    local tempData = {}
    for _, itemData in pairs(curDayTaskData) do
        local serverTaskItemData = serverData[itemData.id] or {}
        if serverTaskItemData then
            table.insert(tempData, {
                id = itemData.id,
                xlsxData = itemData.xlsxData,
                progress = serverTaskItemData.value or 0,
                status = serverTaskItemData.status or 0,
            })
        end
    end
    table.sort(tempData, function(itemData1, itemData2)
        local sortIndex1 = (itemData1.status == 1) and -1 or itemData1.status
        local sortIndex2 = (itemData2.status == 1) and -1 or itemData2.status
        if sortIndex1 ~= sortIndex2 then
            return sortIndex1 < sortIndex2
        else
            return itemData1.id < itemData2.id
        end
    end)
    return tempData
end

--获取各个阶段结束时间
function M:getDayTimer()
    local curServerTimer = UserDataManager:getServerTime()
    local targetTimer = PushUtil:getTargetTimer(1)
    local timer = targetTimer - curServerTimer
    local day, hour, min, sec = GameUtil:getTimeLayoutBySecond(timer)
    if day > 0 then
        hour = hour + day * 24;
    end
    return string.format("%02d:%02d:%02d", hour, min, sec),timer
end

return M